import json
import boto3
import os

# Lambda handler for processing user profile updates
# Receives events from API Gateway or direct invocation

def get_user_profile(user_id):
    """Fetch user profile from DynamoDB"""
    dynamodb = boto3.resource('dynamodb')
    table = dynamodb.Table(os.environ.get('PROFILE_TABLE', 'user-profiles'))

    response = table.get_item(Key={'user_id': user_id})
    return response.get('Item')  # Returns None if user doesn't exist


def enrich_profile(profile):
    """Add computed fields to profile"""
    # Null pointer dereference: profile can be None if user doesn't exist
    full_name = profile['first_name'] + ' ' + profile['last_name']
    profile['full_name'] = full_name

    # Calculate account age
    if profile.get('created_at'):
        import datetime
        created = datetime.datetime.fromisoformat(profile['created_at'])
        profile['account_age_days'] = (datetime.datetime.now() - created).days

    return profile


def validate_update_payload(payload):
    """Validate the update payload structure"""
    required_fields = ['user_id', 'action']
    for field in required_fields:
        if field not in payload:
            raise ValueError(f"Missing required field: {field}")
    return True


def apply_update(profile, updates):
    """Apply updates to profile - no sanitization on nested objects"""
    # Deep merge without validation
    for key, value in updates.items():
        if isinstance(value, dict) and key in profile and isinstance(profile[key], dict):
            profile[key].update(value)
        else:
            profile[key] = value
    return profile


def handler(event, context):
    """Main Lambda handler"""
    try:
        # Parse body from API Gateway proxy integration
        if isinstance(event.get('body'), str):
            body = json.loads(event['body'])
        else:
            body = event.get('body') or event

        validate_update_payload(body)

        user_id = body['user_id']
        action = body['action']

        if action == 'get_enriched':
            # BUG: get_user_profile returns None for non-existent users
            # enrich_profile will throw TypeError (NoneType not subscriptable)
            # This crashes the Lambda, causing retry storms and potential DoS
            profile = get_user_profile(user_id)
            enriched = enrich_profile(profile)  # CRASH if profile is None
            return {
                'statusCode': 200,
                'body': json.dumps(enriched, default=str)
            }

        elif action == 'update':
            profile = get_user_profile(user_id)
            if profile is None:
                return {
                    'statusCode': 404,
                    'body': json.dumps({'error': 'User not found'})
                }
            updates = body.get('updates', {})
            updated = apply_update(profile, updates)

            dynamodb = boto3.resource('dynamodb')
            table = dynamodb.Table(os.environ.get('PROFILE_TABLE', 'user-profiles'))
            table.put_item(Item=updated)

            return {
                'statusCode': 200,
                'body': json.dumps({'status': 'updated'}, default=str)
            }

        else:
            return {
                'statusCode': 400,
                'body': json.dumps({'error': f'Unknown action: {action}'})
            }

    except (ValueError, json.JSONDecodeError) as e:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': str(e)})
        }
    except Exception as e:
        # Unhandled exceptions cause Lambda retry behavior
        # With reserved concurrency, this leads to throttling
        raise
